Object.assign(SNIP,{"l52kien": "TaiKhoan            ← lớp có kiểm tra (Bài 30–33), ném ngoại lệ khi sai (Bài 46)\nNganHang            ← map<string, unique_ptr<TaiKhoan>> (Bài 40, 44): tự giải phóng, không chép nhầm\n  tim(ten)          ← trả về con trỏ dùng nhờ (Bài 44) hoặc optional (Bài 47)\n  chuyen(a, b, x)   ← rút rồi gửi; lỗi ở giữa thì ngoại lệ bay lên nơi xử lý lệnh\nxuLyLenh(...)       ← đọc lệnh, try/catch, in thông báo\nbaoCao              ← sort với lambda, count_if (Bài 41, 42)\ngiao dịch song song ← thread + mutex (Bài 48, 49)"});PRESET_NOTES["l52"]={"Bước 1: lớp TaiKhoan và ngoại lệ": "Số dư chỉ đổi qua gui/rut, và cả hai kiểm tra trước khi đổi. Rút quá số dư ném LoiSoDu (kế thừa runtime_error) nên số dư vẫn đúng là 70.", "Bước 2: NganHang với map và unique_ptr": "map giữ unique_ptr<TaiKhoan>: ngân hàng là chủ duy nhất, hết main thì mọi tài khoản tự được giải phóng. tim trả về con trỏ thường để dùng nhờ (không sở hữu); soDu trả về optional vì tài khoản có thể không tồn tại.", "Bước 3: xử lý lệnh, một chỗ bắt lỗi": "Mỗi lệnh nằm trong try riêng: lệnh sai in thông báo rồi chương trình xử lý lệnh tiếp theo. Các hàm phía dưới chỉ ném, không in gì; chỉ một chỗ (vòng lặp lệnh) quyết định cách báo lỗi cho người dùng.", "Bước 4: báo cáo bằng lambda và thuật toán": "baoCao trả về vector<pair<string, long long>>; sort với lambda xếp số dư giảm dần; count_if với lambda bắt nguong đếm tài khoản đạt ngưỡng.", "Bước 5: giao dịch song song với mutex": "Hai luồng chuyển tiền ngược chiều nhau. Mỗi tài khoản có mutex riêng, và mỗi hàm chỉ giữ một khóa trong một lúc nên không thể deadlock. Tổng hai tài khoản luôn là 200."};EX_HINTS["l52"]=[["Kiểm tra trong gui/rut, ném ngoại lệ; main chỉ bắt và in.", "Đọc x trước khi gọi hàm, để lệnh sai không làm lệch việc đọc các lệnh sau."], ["Lambda so sánh: giá trị lớn hơn đứng trước; bằng nhau thì so tên.", "soLuong trả về nullopt khi không tìm thấy."], ["Mỗi tác vụ chỉ đọc v (truyền cref) nên không cần khóa.", "Trung bình: tong / n (chia nguyên của C++, làm tròn về 0)."]];
/* ===================== BÀI 52 · Dự án tổng hợp ===================== */
/* Bài 52 · Dự án tổng hợp
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P52=[{label:"Bước 1: lớp TaiKhoan và ngoại lệ",input:"",code:"#include <iostream>\n#include <string>\n#include <stdexcept>\nusing namespace std;\n\nclass LoiSoDu : public runtime_error {\npublic:\n    LoiSoDu() : runtime_error(\"khong du so du\") {}\n};\nclass TaiKhoan {\n    string ten;\n    long long du = 0;\npublic:\n    TaiKhoan(string t) : ten(t) {}\n    const string& layTen() const { return ten; }\n    long long soDu() const { return du; }\n    void gui(long long x) {\n        if (x <= 0) throw invalid_argument(\"so tien phai duong\");\n        du += x;\n    }\n    void rut(long long x) {\n        if (x <= 0) throw invalid_argument(\"so tien phai duong\");\n        if (x > du) throw LoiSoDu();\n        du -= x;\n    }\n};\nint main() {\n    TaiKhoan a(\"An\");\n    a.gui(100);\n    try {\n        a.rut(30);\n        cout << \"Con \" << a.soDu() << \"\\n\";\n        a.rut(500);\n        cout << \"Khong in\\n\";\n    } catch (const LoiSoDu& e) {\n        cout << \"Loi: \" << e.what() << \"\\n\";\n    }\n    try {\n        a.gui(-5);\n    } catch (const exception& e) {\n        cout << \"Loi: \" << e.what() << \"\\n\";\n    }\n    cout << a.layTen() << \" con \" << a.soDu() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Bước 2: NganHang với map và unique_ptr",input:"",code:"#include <iostream>\n#include <string>\n#include <stdexcept>\n#include <map>\n#include <memory>\n#include <optional>\n#include <vector>\nusing namespace std;\n\nclass LoiSoDu : public runtime_error {\npublic:\n    LoiSoDu() : runtime_error(\"khong du so du\") {}\n};\nclass TaiKhoan {\n    string ten;\n    long long du = 0;\npublic:\n    TaiKhoan(string t) : ten(t) {}\n    const string& layTen() const { return ten; }\n    long long soDu() const { return du; }\n    void gui(long long x) {\n        if (x <= 0) throw invalid_argument(\"so tien phai duong\");\n        du += x;\n    }\n    void rut(long long x) {\n        if (x <= 0) throw invalid_argument(\"so tien phai duong\");\n        if (x > du) throw LoiSoDu();\n        du -= x;\n    }\n};\nclass NganHang {\n    map<string, unique_ptr<TaiKhoan>> ds;\npublic:\n    void mo(const string& ten) {\n        if (ds.count(ten)) throw invalid_argument(\"tai khoan da ton tai\");\n        ds[ten] = make_unique<TaiKhoan>(ten);\n    }\n    TaiKhoan* tim(const string& ten) {\n        auto it = ds.find(ten);\n        if (it == ds.end()) return nullptr;\n        return it->second.get();\n    }\n    TaiKhoan& lay(const string& ten) {\n        TaiKhoan* p = tim(ten);\n        if (!p) throw out_of_range(\"khong co tai khoan \" + ten);\n        return *p;\n    }\n    optional<long long> soDu(const string& ten) {\n        TaiKhoan* p = tim(ten);\n        if (!p) return nullopt;\n        return p->soDu();\n    }\n    void chuyen(const string& a, const string& b, long long x) {\n        TaiKhoan& A = lay(a);\n        TaiKhoan& B = lay(b);\n        A.rut(x);\n        B.gui(x);\n    }\n    vector<pair<string, long long>> baoCao() const {\n        vector<pair<string, long long>> v;\n        for (const auto& [ten, p] : ds) v.push_back({ten, p->soDu()});\n        return v;\n    }\n};\nint main() {\n    NganHang nh;\n    nh.mo(\"An\");\n    nh.mo(\"Binh\");\n    nh.lay(\"An\").gui(200);\n    nh.chuyen(\"An\", \"Binh\", 50);\n    string ds[] = {\"An\", \"Binh\", \"Chi\"};\n    for (string ten : ds) {\n        auto du = nh.soDu(ten);\n        if (du) cout << ten << \": \" << *du << \"\\n\";\n        else cout << ten << \": khong co tai khoan\\n\";\n    }\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Bước 3: xử lý lệnh, một chỗ bắt lỗi",input:"7\nMO An\nMO Binh\nGUI An 100\nRUT Binh 10\nCHUYEN An Binh 40\nCHUYEN An Chi 5\nMO An",code:"#include <iostream>\n#include <string>\n#include <stdexcept>\n#include <map>\n#include <memory>\n#include <optional>\n#include <vector>\nusing namespace std;\n\nclass LoiSoDu : public runtime_error {\npublic:\n    LoiSoDu() : runtime_error(\"khong du so du\") {}\n};\nclass TaiKhoan {\n    string ten;\n    long long du = 0;\npublic:\n    TaiKhoan(string t) : ten(t) {}\n    const string& layTen() const { return ten; }\n    long long soDu() const { return du; }\n    void gui(long long x) {\n        if (x <= 0) throw invalid_argument(\"so tien phai duong\");\n        du += x;\n    }\n    void rut(long long x) {\n        if (x <= 0) throw invalid_argument(\"so tien phai duong\");\n        if (x > du) throw LoiSoDu();\n        du -= x;\n    }\n};\nclass NganHang {\n    map<string, unique_ptr<TaiKhoan>> ds;\npublic:\n    void mo(const string& ten) {\n        if (ds.count(ten)) throw invalid_argument(\"tai khoan da ton tai\");\n        ds[ten] = make_unique<TaiKhoan>(ten);\n    }\n    TaiKhoan* tim(const string& ten) {\n        auto it = ds.find(ten);\n        if (it == ds.end()) return nullptr;\n        return it->second.get();\n    }\n    TaiKhoan& lay(const string& ten) {\n        TaiKhoan* p = tim(ten);\n        if (!p) throw out_of_range(\"khong co tai khoan \" + ten);\n        return *p;\n    }\n    optional<long long> soDu(const string& ten) {\n        TaiKhoan* p = tim(ten);\n        if (!p) return nullopt;\n        return p->soDu();\n    }\n    void chuyen(const string& a, const string& b, long long x) {\n        TaiKhoan& A = lay(a);\n        TaiKhoan& B = lay(b);\n        A.rut(x);\n        B.gui(x);\n    }\n    vector<pair<string, long long>> baoCao() const {\n        vector<pair<string, long long>> v;\n        for (const auto& [ten, p] : ds) v.push_back({ten, p->soDu()});\n        return v;\n    }\n};\nint main() {\n    NganHang nh;\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        string lenh, a, b;\n        long long x;\n        cin >> lenh;\n        try {\n            if (lenh == \"MO\") {\n                cin >> a;\n                nh.mo(a);\n                cout << \"Mo \" << a << \"\\n\";\n            } else if (lenh == \"GUI\") {\n                cin >> a >> x;\n                nh.lay(a).gui(x);\n                cout << \"OK\\n\";\n            } else if (lenh == \"RUT\") {\n                cin >> a >> x;\n                nh.lay(a).rut(x);\n                cout << \"OK\\n\";\n            } else if (lenh == \"CHUYEN\") {\n                cin >> a >> b >> x;\n                nh.chuyen(a, b, x);\n                cout << \"OK\\n\";\n            }\n        } catch (const exception& e) {\n            cout << \"Loi: \" << e.what() << \"\\n\";\n        }\n    }\n    auto bc = nh.baoCao();\n    for (const auto& [ten, du] : bc) cout << ten << \" \" << du << \"\\n\";\n    return 0;\n}"},{label:"Bước 4: báo cáo bằng lambda và thuật toán",input:"",code:"#include <iostream>\n#include <string>\n#include <stdexcept>\n#include <map>\n#include <memory>\n#include <optional>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass LoiSoDu : public runtime_error {\npublic:\n    LoiSoDu() : runtime_error(\"khong du so du\") {}\n};\nclass TaiKhoan {\n    string ten;\n    long long du = 0;\npublic:\n    TaiKhoan(string t) : ten(t) {}\n    const string& layTen() const { return ten; }\n    long long soDu() const { return du; }\n    void gui(long long x) {\n        if (x <= 0) throw invalid_argument(\"so tien phai duong\");\n        du += x;\n    }\n    void rut(long long x) {\n        if (x <= 0) throw invalid_argument(\"so tien phai duong\");\n        if (x > du) throw LoiSoDu();\n        du -= x;\n    }\n};\nclass NganHang {\n    map<string, unique_ptr<TaiKhoan>> ds;\npublic:\n    void mo(const string& ten) {\n        if (ds.count(ten)) throw invalid_argument(\"tai khoan da ton tai\");\n        ds[ten] = make_unique<TaiKhoan>(ten);\n    }\n    TaiKhoan* tim(const string& ten) {\n        auto it = ds.find(ten);\n        if (it == ds.end()) return nullptr;\n        return it->second.get();\n    }\n    TaiKhoan& lay(const string& ten) {\n        TaiKhoan* p = tim(ten);\n        if (!p) throw out_of_range(\"khong co tai khoan \" + ten);\n        return *p;\n    }\n    optional<long long> soDu(const string& ten) {\n        TaiKhoan* p = tim(ten);\n        if (!p) return nullopt;\n        return p->soDu();\n    }\n    void chuyen(const string& a, const string& b, long long x) {\n        TaiKhoan& A = lay(a);\n        TaiKhoan& B = lay(b);\n        A.rut(x);\n        B.gui(x);\n    }\n    vector<pair<string, long long>> baoCao() const {\n        vector<pair<string, long long>> v;\n        for (const auto& [ten, p] : ds) v.push_back({ten, p->soDu()});\n        return v;\n    }\n};\nint main() {\n    NganHang nh;\n    string ten[] = {\"An\", \"Binh\", \"Chi\", \"Dung\"};\n    long long tien[] = {300, 50, 120, 0};\n    for (int i = 0; i < 4; i++) {\n        nh.mo(ten[i]);\n        if (tien[i] > 0) nh.lay(ten[i]).gui(tien[i]);\n    }\n    auto bc = nh.baoCao();\n    sort(bc.begin(), bc.end(), [](const pair<string, long long>& x, const pair<string, long long>& y) {\n        return x.second > y.second;\n    });\n    for (const auto& [t, d] : bc) cout << t << \" \" << d << \"\\n\";\n    long long nguong = 100;\n    int giau = count_if(bc.begin(), bc.end(), [nguong](const pair<string, long long>& x) { return x.second >= nguong; });\n    cout << giau << \" tai khoan co tu \" << nguong << \" tro len\\n\";\n    return 0;\n}"},{label:"Bước 5: giao dịch song song với mutex",input:"",code:"#include <iostream>\n#include <string>\n#include <stdexcept>\n#include <thread>\n#include <mutex>\n#include <vector>\nusing namespace std;\n\nclass TaiKhoanAnToan {\n    long long du;\n    mutex m;\npublic:\n    TaiKhoanAnToan(long long d) : du(d) {}\n    bool rut(long long x) {\n        lock_guard<mutex> k(m);\n        if (x > du) return false;\n        du -= x;\n        return true;\n    }\n    void gui(long long x) {\n        lock_guard<mutex> k(m);\n        du += x;\n    }\n    long long soDu() {\n        lock_guard<mutex> k(m);\n        return du;\n    }\n};\nvoid chuyen(TaiKhoanAnToan& a, TaiKhoanAnToan& b, long long x, int lan) {\n    for (int i = 0; i < lan; i++) {\n        if (a.rut(x)) b.gui(x);\n    }\n}\nint main() {\n    TaiKhoanAnToan an(100), binh(100);\n    thread t1(chuyen, ref(an), ref(binh), 10, 4);\n    thread t2(chuyen, ref(binh), ref(an), 5, 4);\n    t1.join();\n    t2.join();\n    cout << \"An: \" << an.soDu() << \", Binh: \" << binh.soDu() << \"\\n\";\n    cout << \"Tong van la \" << an.soDu() + binh.soDu() << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"}]}];
