makeEx2(document.getElementById("ex-l52"),sim52,[{t:"Dự án 1: Xử lý lệnh tài khoản",d:"Một tài khoản bắt đầu với số dư 0. Nhập q lệnh: <code>GUI x<\/code>, <code>RUT x<\/code>, <code>XEM<\/code>. Viết lớp TaiKhoan: gui/rut ném <code>invalid_argument(\"so tien khong hop le\")<\/code> khi x ≤ 0, rut ném <code>runtime_error(\"khong du tien\")<\/code> khi x &gt; số dư. Vòng lặp lệnh bắt ngoại lệ: lệnh đúng in <code>OK<\/code>, lệnh sai in <code>Loi: <\/code> kèm what(), <code>XEM<\/code> in số dư.",tests:[{in:"6\nGUI 100\nRUT 30\nRUT 500\nGUI -5\nXEM\nRUT 70",out:"OK\nOK\nLoi: khong du tien\nLoi: so tien khong hop le\n70\nOK"},{in:"2\nXEM\nRUT 1",out:"0\nLoi: khong du tien"}],start:"#include <iostream>\n#include <string>\n#include <stdexcept>\nusing namespace std;\n\nclass TaiKhoan {\n    long long du = 0;\npublic:\n    void gui(long long x) { du += x; }\n    void rut(long long x) { du -= x; }\n    long long soDu() const { return du; }\n};\nint main() {\n    TaiKhoan tk;\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        string lenh;\n        cin >> lenh;\n        // GUI x, RUT x, XEM; bắt ngoại lệ\n    }\n    return 0;\n}",need:/throw[\s\S]*try[\s\S]*catch/,needMsg:"Hãy ném ngoại lệ trong lớp và bắt trong vòng lặp lệnh."},{t:"Dự án 2: Báo cáo kho hàng",d:"Nhập n mặt hàng, mỗi dòng: tên, số lượng, đơn giá. Lưu trong <code>vector<\/code> của struct. In danh sách theo giá trị tồn kho (số lượng × đơn giá) giảm dần, cùng giá trị thì theo tên tăng dần, mỗi dòng <code>ten gia_tri<\/code> (dùng sort với lambda). Rồi đọc q tên cần tra: viết hàm trả về <code>optional&lt;long long&gt;<\/code> số lượng, in số lượng hoặc <code>khong co<\/code>.",tests:[{in:"3\nbut 10 3\nvo 5 12\ntay 20 3\n2\nvo\nthuoc",out:"tay 60\nvo 60\nbut 30\n5\nkhong co"},{in:"1\na 1 1\n1\na",out:"a 1\n1"}],start:"#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <optional>\nusing namespace std;\n\nstruct MatHang {\n    string ten;\n    long long sl, gia;\n};\n// optional<long long> soLuong(const vector<MatHang>& kho, const string& ten) { ... }\nint main() {\n    int n;\n    cin >> n;\n    vector<MatHang> kho(n);\n    for (auto& m : kho) cin >> m.ten >> m.sl >> m.gia;\n    // sort với lambda, in\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        string t;\n        cin >> t;\n    }\n    return 0;\n}",need:/sort\s*\([^;]*\[[\s\S]*optional\s*<|optional\s*<[\s\S]*sort\s*\([^;]*\[/,needMsg:"Hãy dùng sort với lambda và hàm trả về optional."},{t:"Dự án 3: Thống kê song song",d:"Nhập n và n số nguyên (n ≥ 2). Chia dãy thành hai nửa (nửa đầu n/2 phần tử). Dùng hai tác vụ <code>async<\/code>, mỗi tác vụ trả về một <code>pair&lt;long long, int&gt;<\/code> gồm tổng và số lớn nhất của nửa mình. Gộp lại, in tổng, số lớn nhất và trung bình cộng (lấy phần nguyên, chia nguyên), mỗi số một dòng.",tests:[{in:"6\n4 9 1 7 3 6",out:"30\n9\n5"},{in:"2\n-5 -2",out:"-7\n-2\n-3"}],start:"#include <iostream>\n#include <future>\n#include <vector>\n#include <utility>\nusing namespace std;\n\npair<long long, int> thongKe(const vector<int>& v, int dau, int cuoi) {\n    // tổng và max của v[dau..cuoi-1]\n    return {0, 0};\n}\nint main() {\n    int n;\n    cin >> n;\n    vector<int> v(n);\n    for (int& x : v) cin >> x;\n    // auto f1 = async(launch::async, thongKe, cref(v), 0, n / 2); ...\n    return 0;\n}",need:/async[\s\S]*async/,needMsg:"Hãy dùng hai tác vụ async."}]);

makeQuiz("quiz52","score52",[{"q": "Trong dự án, chỗ nào nên bắt ngoại lệ và in thông báo lỗi?", "o": ["Trong mọi hàm của TaiKhoan", "Ở nơi xử lý lệnh của người dùng (vòng lặp lệnh)", "Trong hàm hủy", "Không cần bắt"], "a": 1, "e": "Các hàm phía dưới chỉ ném; nơi biết cách báo cho người dùng mới bắt."}, {"q": "Vì sao NganHang giữ <code>map&lt;string, unique_ptr&lt;TaiKhoan&gt;&gt;<\/code>?", "o": ["Để chép tài khoản dễ hơn", "Ngân hàng là chủ duy nhất, tài khoản tự được giải phóng, không cần viết hàm hủy", "Vì map không chứa được đối tượng", "Để chạy nhanh hơn"], "a": 1, "e": "unique_ptr thể hiện quyền sở hữu duy nhất và RAII."}, {"q": "Hàm tìm tài khoản theo tên, có thể không có. Kiểu trả về hợp lý:", "o": ["TaiKhoan (bản chép)", "optional<long long> hoặc con trỏ dùng nhờ TaiKhoan*", "int (−1 khi không có)", "void"], "a": 1, "e": "optional / con trỏ thường (dùng nhờ, có thể nullptr) nói rõ khả năng không tìm thấy."}, {"q": "Hai luồng cùng gửi/rút trên một tài khoản. Cần:", "o": ["Không cần gì", "Mutex trong tài khoản, khóa ở mọi hàm đọc/ghi số dư", "Chỉ khóa hàm rút", "Dùng hai tài khoản"], "a": 1, "e": "Mọi truy cập dữ liệu dùng chung đều phải được bảo vệ."}]);

